{
  "bioavailability_prediction": "high",
  "confidence": "low",
  "revision_action": "weaken",
  "supportive_card_ids": [
    "C30","C31","C33","C22","C23","C25","C26","C34","C37",
    "C08","C13","C14","C01","C02","C05","C11","C21","C24","C28","C36",
    "C135","C164"
  ],
  "contradictory_card_ids": ["C180","C226"],
  "prediction_basis_card_ids": [
    "C30","C31","C33","C22","C23","C25","C26","C34","C37",
    "C08","C13","C14","C01","C02","C05","C11","C21","C24","C28","C36"
  ],
  "claims": [
    {
      "claim": "Gold-context aryloxypropanolamine beta-blockers have measured absolute oral bioavailability well above the 20% threshold in humans: pamatolol 64.9–103.5% (50 mg) and 90.3–150.5% (200 mg); practolol 90–100%; pindolol ~53–100% (most estimates 75–80%); bufuralol 0.52–0.83; diacetolol 0.30–0.43.",
      "card_ids": ["C30","C31","C33","C22","C23","C25","C26","C34","C37","C08","C13","C14","C01","C02","C05","C11","C21","C24","C28","C36"]
    },
    {
      "claim": "L4 records for structurally related beta-blockers show adequate aqueous solubility (urea-containing aryloxypropanolamine analog 1.0 mg/mL; celiprolol 15.2 mg/mL at pH 7.4), supporting adequate intestinal dissolution for this scaffold.",
      "card_ids": ["C135","C164"]
    },
    {
      "claim": "L5 C180 directly identifies talinolol (the query scaffold) as a beta-blocker with in vivo intestinal secretion and predominant basolateral-to-apical transport in Caco-2, indicating P-gp-mediated gut-wall efflux; C226 shows P-gp inhibition increases celiprolol plasma concentration, supporting that this urea-containing beta-blocker class can undergo intestinal efflux.",
      "card_ids": ["C180","C226"]
    },
    {
      "claim": "No record provides a measured absolute F for talinolol under rifampin or otherwise demonstrates F < 20%; in vitro efflux and rifampin induction are mechanistic and do not by themselves establish sub-threshold bioavailability.",
      "card_ids": ["C180","C226"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "high",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C180","C226"]
    }
  ],
  "evidence_gaps": [
    "No direct measured absolute oral bioavailability for talinolol (query) under rifampin co-treatment.",
    "No talinolol-specific rifampin interaction record; L3 lenvatinib-rifampin records (C98, C121, C125) are for a different molecule and lack IV comparator.",
    "C180 establishes intestinal secretion/efflux direction but not magnitude; no F value or AUC ratio with rifampin is provided.",
    "L1 analog F values are for other beta-blockers without rifampin; transferability is limited by P-gp efflux and induction.",
    "Physicochemical prior is mixed; high ionization may reduce passive permeability but is not threshold-negative."
  ],
  "decision_summary": "L1/L2 gold evidence for structurally similar beta-blockers shows absolute F well above 20%; L5 C180 directly identifies talinolol as a P-gp efflux substrate with intestinal secretion, and rifampin induction could reduce exposure, but no record demonstrates F < 20% under rifampin. Prediction remains high; confidence is lowered due to query-specific efflux and lack of rifampin quantification."
}

